        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Anxiety symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Longstanding mild anxiety usually manageable; for the past 4–6 weeks feels more wound up, especially at work on a noisy site with overtime; describes being more on edge than usual, restless and keyed up, with mildly reduced concentration at work especially late afternoon."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Sleep symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Sleep onset delay of 30–60 minutes; occasional early waking 1–2 times per week."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Reported mood and associated symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mood described as pretty steady, cranky and anxious; no anhedonia. Denies panic, chest pain, shortness of breath, palpitations, weight loss, fevers, night sweats, suicidal ideation, or thoughts of self-harm."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "GAD-7 score"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 8
        },
        "note": [
          {
            "text": "Recorded as mild."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "PHQ-9 score"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 5
        },
        "note": [
          {
            "text": "Recorded as mild and not functionally impairing."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Smoking history and nicotine dependence"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Smokes approximately 20–25 cigarettes per day for approximately 30 years. First cigarette is within 10–15 minutes of waking; assessed as high dependence. Anxiety is worse when longer between cigarettes. Previous cold-turkey quit attempt lasted approximately one week before relapse with irritability and poor sleep. Nicotine patch alone approximately five years ago helped somewhat but cravings persisted. Cutting down causes irritability, anxiety, reduced concentration, and feeling snappy. Currently wants to cut back first and is not ready for a full quit."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Alcohol and other drug use"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports 2–3 beers most nights, stable for years; denies other drug use."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
